export const defaults={forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD',run:'ShiftLeft',jump:'Space',interact:'KeyE',sword:'KeyJ',punch:'KeyK',swap:'Tab',stretch:'KeyQ',giant:'KeyF',small:'KeyC',bridge:'KeyB',ladder:'KeyL',recover:'KeyR'};
export const controlNames={forward:'Andar para frente',back:'Andar para trás',left:'Esquerda',right:'Direita',run:'Correr',jump:'Pular',interact:'Interagir',sword:'Espada',punch:'Soco',swap:'Trocar Finn/Jake',stretch:'Jake esticar',giant:'Jake gigante',small:'Jake pequeno',bridge:'Jake ponte',ladder:'Jake escada',recover:'Voltar ao ponto seguro'};
export const keyLabel=code=>code.replace(/^Key/,'').replace(/^Digit/,'').replace('ShiftLeft','Shift').replace('Space','Espaço');
export function validBindings(value){return !!value&&Object.keys(defaults).every(k=>typeof value[k]==='string'&&/^(Key[A-Z]|Digit[0-9]|Tab|Space|ShiftLeft|ControlLeft|AltLeft|ArrowUp|ArrowDown|ArrowLeft|ArrowRight)$/.test(value[k]))&&Object.entries(value).every(([action,code])=>!code.startsWith('Arrow')||({ArrowUp:'forward',ArrowDown:'back',ArrowLeft:'left',ArrowRight:'right'}[code]===action))&&new Set(Object.values(value)).size===Object.keys(defaults).length;}
